import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.8tqBsFWt.js";const u=JSON.parse('{"title":"Salary Band Import Runbook","description":"","frontmatter":{},"headers":[],"relativePath":"operations/salary-band-import.md","filePath":"operations/salary-band-import.md"}'),i={name:"operations/salary-band-import.md"};function r(s,e,l,d,h,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="salary-band-import-runbook" tabindex="-1">Salary Band Import Runbook <a class="header-anchor" href="#salary-band-import-runbook" aria-label="Permalink to &quot;Salary Band Import Runbook&quot;">​</a></h1><p>Use this runbook to turn published federal wage percentiles into a starting salary ladder for a discipline. There are two ways to do this, both backed by the same fetch and geographic-fallback logic (<code>lib/wage-data.js</code>), so they can never disagree on a result.</p><p><strong>The normal path is the console.</strong> On the <strong>Bands</strong> tab of <code>/console/users</code> (<code>/console/users?tab=bands</code>, owner only), an owner clicks <strong>Refresh from wage data</strong> to see, per discipline, the current ladder beside what the published data proposes — and applies the ones they want, one discipline at a time. <strong>Fetching never writes.</strong> Nothing is saved until an owner clicks Apply on a specific discipline, and nothing ever runs on a schedule — see &quot;Fetching and applying stay separate&quot; below.</p><p><strong>The CLI (<code>scripts/fetch-salary-bands.js</code>) remains available</strong> as the operator/debugging route — useful for a first-time setup check, or for diagnosing why a discipline isn&#39;t producing a proposal, without needing a browser session. It writes nothing either; it prints numbers for a human to review.</p><hr><h2 id="the-console-flow" tabindex="-1">The console flow <a class="header-anchor" href="#the-console-flow" aria-label="Permalink to &quot;The console flow&quot;">​</a></h2><ol><li><strong>Set the tenant&#39;s HQ location.</strong> In <code>/admin</code>, find the tenant row and set <strong>HQ Location</strong> (e.g. <code>Ann Arbor, MI</code>). See the tenant-shape section of <code>CLAUDE.md</code>.</li><li><strong>Map at least one discipline to an occupation.</strong> On <code>/console/disciplines</code>, open a discipline&#39;s Edit modal and pick its occupation from the grouped picker. Disciplines with no mapping are skipped and listed — never guessed at.</li><li><strong>Set the CareerOneStop API credentials</strong> as process environment variables (see Prerequisites below). Without both, the Refresh button on the Bands tab doesn&#39;t appear — the page names the missing prerequisite instead of failing silently.</li><li>On the Bands tab, click <strong>Refresh from wage data</strong>. Each mapped discipline gets a row: which occupation, which geography tier the numbers came from, the existing ladder, the proposed one, and an Apply button — present only when the proposal differs from what&#39;s already set.</li><li>Click <strong>Apply</strong> on the disciplines you want. Each Apply writes only that discipline&#39;s ladder, through the same validation as typing the numbers in by hand. Nothing else changes until you click Apply.</li></ol><p>A page refresh re-runs the fetch (there&#39;s nowhere to stash the proposals between requests without adding session state) — expect roughly one wage-API call per mapped discipline each time you click Refresh.</p><hr><h2 id="prerequisites-both-paths" tabindex="-1">Prerequisites (both paths) <a class="header-anchor" href="#prerequisites-both-paths" aria-label="Permalink to &quot;Prerequisites (both paths)&quot;">​</a></h2><ol><li><p><strong>The tenant&#39;s HQ location must be set.</strong> In <code>/admin</code>, find the tenant row and set <strong>HQ Location</strong> (e.g. <code>Ann Arbor, MI</code>). See the tenant-shape section of <code>CLAUDE.md</code>. For the CLI only, if it isn&#39;t set, pass <code>--location=&quot;City, ST&quot;</code> on the command line instead.</p></li><li><p><strong>At least one discipline must have an occupation code mapped.</strong> On <code>/console/disciplines</code>, open a discipline&#39;s Edit modal and pick its occupation from the grouped picker. Disciplines with no mapping are skipped and listed — never guessed at.</p></li><li><p><strong>CareerOneStop API credentials.</strong> Register for free at <a href="https://www.careeronestop.org/Developers/WebAPI/registration.aspx" target="_blank" rel="noreferrer">https://www.careeronestop.org/Developers/WebAPI/registration.aspx</a>, then set:</p><ul><li><code>CAREERONESTOP_USER_ID</code></li><li><code>CAREERONESTOP_TOKEN</code></li></ul><p>Do not commit these anywhere, and do not add them to a tenant file — they are process environment variables only.</p></li></ol><hr><h2 id="running-the-cli" tabindex="-1">Running the CLI <a class="header-anchor" href="#running-the-cli" aria-label="Permalink to &quot;Running the CLI&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node scripts/fetch-salary-bands.js --tenant=&lt;id&gt; [--location=&quot;Ann Arbor, MI&quot;] [--dry-run]</span></span></code></pre></div><ul><li><code>--tenant=&lt;id&gt;</code> — required, matches the tenants file.</li><li><code>--location=&lt;..&gt;</code> — optional; overrides the tenant&#39;s stored <code>hq_location</code> for this run only.</li><li><code>--dry-run</code> — lists which disciplines would be queried and with what location, without making any network calls or requiring API credentials. Use this to sanity-check the setup before spending an API call.</li></ul><hr><h2 id="reading-the-output" tabindex="-1">Reading the output <a class="header-anchor" href="#reading-the-output" aria-label="Permalink to &quot;Reading the output&quot;">​</a></h2><p>Both the console panel and the CLI report the same things per mapped discipline — the CLI prints them to the terminal:</p><ul><li>The occupation title and code it queried.</li><li><strong>Which geography tier the numbers came from</strong> — <code>metro/local</code>, <code>state</code>, or <code>national</code>. A ladder built on national numbers for a company in a small town is a legitimate answer, but you need to know that&#39;s what you&#39;re looking at before you paste it in.</li><li>The four raw wage anchors (10th, 25th, 75th, 90th percentile annual wage).</li><li>The five resulting ladder boundaries, formatted for pasting straight into the salary ladder modal on the Bands tab (floor, the three interior boundaries, ceiling).</li></ul><p>At the end, the CLI prints a summary line: how many disciplines produced a ladder, how many were skipped or failed, and how many had no occupation mapped at all. The console panel shows the same per-discipline picture as a table instead.</p><p><strong>The published figures are a starting point, not a verdict.</strong> Some businesses deliberately pay above the local market to win talent; some pay below it and compete on other things. Treat a proposed ladder as a first draft to sanity-check against your own pay strategy, not a number to accept unquestioned.</p><hr><h2 id="why-some-disciplines-don-t-get-a-ladder" tabindex="-1">Why some disciplines don&#39;t get a ladder <a class="header-anchor" href="#why-some-disciplines-don-t-get-a-ladder" aria-label="Permalink to &quot;Why some disciplines don&#39;t get a ladder&quot;">​</a></h2><p>The import refuses rather than approximates, on both paths. You&#39;ll see one of these reasons:</p><ul><li><strong>&quot;no occupation mapped&quot;</strong> — the discipline has no <code>soc_code</code> set. Set one on <code>/console/disciplines</code> and refresh or re-run.</li><li><strong>&quot;top-coded/censored value&quot;</strong> — published wage data caps very high earners at a bound (e.g. &quot;≥ $239,200&quot;) rather than a real figure. Arithmetic on a capped value is meaningless, so the import refuses that geography tier and tries the next broader one; if every tier is capped, the discipline is reported unavailable.</li><li><strong>&quot;no data published for this geography&quot;</strong> — the tier is simply empty for that occupation × location (a suppressed cell). The import falls through to the next broader tier automatically.</li><li><strong>A data-anomaly refusal</strong> (e.g. two percentiles came back equal) — the published figures for that geography don&#39;t support a valid ladder. This is reported directly; it does not fall through to a different tier, since the data existed but didn&#39;t make sense.</li><li><strong>An HTTP or network failure</strong> — reported with the status code. The import never substitutes a different geography to paper over a transport error.</li></ul><h2 id="what-the-import-never-does" tabindex="-1">What the import never does <a class="header-anchor" href="#what-the-import-never-does" aria-label="Permalink to &quot;What the import never does&quot;">​</a></h2><ul><li>It never mixes geography tiers within one ladder (no splicing a national 90th onto a local 25th).</li><li>It never treats a capped/censored figure as if it were a real number.</li><li>It never guesses an occupation for an unmapped discipline.</li><li>It never applies a ladder without an explicit, per-discipline action — no auto-apply, no &quot;apply all&quot;, no scheduled refresh. See &quot;Fetching and applying stay separate&quot; below.</li></ul><h2 id="fetching-and-applying-stay-separate" tabindex="-1">Fetching and applying stay separate <a class="header-anchor" href="#fetching-and-applying-stay-separate" aria-label="Permalink to &quot;Fetching and applying stay separate&quot;">​</a></h2><p>Fetching (the CLI, and clicking Refresh on the console) only ever reads and prints or displays — it never writes to the database, calls a write endpoint, or posts to the audit channel. On the console, applying a proposal is a separate, explicit click per discipline, through the same <code>set_discipline_ladder</code> path a hand-typed ladder would use — so a rejected proposal fails exactly the same way a manual entry would. There is no &quot;apply all&quot; button and nothing runs on a schedule: a band that has been deliberately calibrated against a real pay strategy should never be silently overwritten by a data refresh.</p><h2 id="after-running-the-cli" tabindex="-1">After running the CLI <a class="header-anchor" href="#after-running-the-cli" aria-label="Permalink to &quot;After running the CLI&quot;">​</a></h2><p>Copy the five printed boundaries into the discipline&#39;s salary ladder modal on the Bands tab (owner only), or re-run the same lookup from the console&#39;s Refresh button and click Apply there instead. Nothing changes until you do.</p>',31)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
